
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mpw1k_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mpw1k", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.543925551689380e+00, -2.496202833634258e+00, -2.429349602225602e+00, -2.336779147813620e+00, -2.210721153729859e+00, -2.043121246752506e+00, -1.827772879102900e+00, -1.564147157105928e+00, -1.262484931984269e+00, -9.463443745102857e-01, -6.424481370899628e-01, -4.467443534943996e-01, -3.920491435902783e-01, -3.214467653517987e-01, -2.304738369816854e-01, -1.451142161117125e-01, -8.305171168226345e-02, -2.817816458312293e-02, -7.210923411124740e-04, -1.801109472481036e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


